mapper.select:
/*selectMasterMdAmMasterCodeManageList*/
SELECT CODE , TEXT1 , TEXT2 , TEXT3 , TEXT4 , TYPE , A.TEXT5 , A.TEXT6 , CODE AS ORG_CODE
, FLAG , ( SELECT DECODE(COUNT(*),0,'XX','OO') AS MODIFY_FLAG FROM ICOMBDGT /* 부서별 예산관리 */ WHERE 1=1 AND BUYER = #{st_com_code} AND ACCOUNT_TYPE = A.CODE AND TO_CHAR(SYSDATE, 'YYYYMMDD') BETWEEN FROM_DATE AND TO_DATE ) AS MODIFY_FLAG
FROM ICOMCOD2 A /* 회사별 코드관리 */ WHERE 1=1 AND TYPE = #{st_type}
AND A.COMPANY_CODE = #{SESSION_BUYER_CODE}
AND A.COMPANY_CODE = #{st_com_code}
AND CODE = #{st_code}
AND UPPER(TEXT1) LIKE UPPER( '%' || #{st_name} || '%')
ORDER BY CODE

/*selectMasterMdAmMasterCodeManageList_Dept*/
SELECT DE.CODE , DE.TEXT1 , DE.TEXT2 , DE.TEXT3 , DE.TEXT4 , DE.CODE AS ORG_CODE
, DECODE(NVL(PS.CODE, '0'), '0', DECODE(DE.TYPE_FLAG, 'A', 'N', DE.TYPE_FLAG), 'Y') AS DEPT_TYPE , DECODE(NVL(PS.CODE, '0'), '0', DECODE(DE.TYPE_FLAG, 'A', 'N', DE.TYPE_FLAG), 'Y') AS ORG_DEPT_TYPE
, DECODE(NVL(PS.CODE, '0'), '0', 'N', 'Y') AS DEPT_TYPE , DECODE(NVL(PS.CODE, '0'), '0', 'N', 'Y') AS ORG_DEPT_TYPE
, DECODE(NVL(PS.CODE, '0'), '0', DECODE(DE.TYPE_FLAG, 'A', 'N', DE.TYPE_FLAG), 'Y') AS DEPT_TYPE , DECODE(NVL(PS.CODE, '0'), '0', DECODE(DE.TYPE_FLAG, 'A', 'N', DE.TYPE_FLAG), 'Y') AS ORG_DEPT_TYPE
FROM ICOMCOD2 DE /* 회사별 코드관리 */ , ICOMCOD2 PS /* 회사별 코드관리 */ WHERE 1=1 AND DE.CODE = PS.CODE(+) AND DE.COMPANY_CODE = PS.COMPANY_CODE(+) AND DE.TYPE = #{st_type} AND PS.TYPE(+) ='C004'
AND DE.COMPANY_CODE = #{SESSION_BUYER_CODE}
AND DE.COMPANY_CODE = #{st_com_code}
AND DE.CODE = #{st_code}
AND UPPER(DE.TEXT1) LIKE UPPER('%' || #{st_name} || '%')
AND DECODE(NVL(PS.CODE, '0'), '0', 'N', 'Y') = #{st_dept_type}
ORDER BY DEPT_TYPE DESC , DE.CODE

/*selectMasterMdAmMasterCodeManageList_Dept_v2*/
SELECT DE.CODE , DE.TEXT1 , DE.TEXT2 , DE.TEXT3 , DE.TEXT4 , DE.CODE AS ORG_CODE , DECODE(NVL(PS.CODE, '0'), '0', 'N', 'Y') AS DEPT_TYPE , DECODE(NVL(PS.CODE, '0'), '0', 'N', 'Y') AS DEPT_TYPE_TEXT , DECODE(NVL(PS.CODE, '0'), '0', 'N', 'Y') AS ORG_DEPT_TYPE FROM ICOMCOD2 DE /* 회사별 코드관리 */ , ICOMCOD2 PS /* 회사별 코드관리 */ WHERE 1=1 AND DE.CODE = PS.CODE(+) AND DE.COMPANY_CODE = PS.COMPANY_CODE(+) AND DE.TYPE = #{st_type} AND PS.TYPE(+) ='C004'
AND DE.COMPANY_CODE = #{SESSION_BUYER_CODE}
AND DE.COMPANY_CODE = #{st_com_code}
AND DE.CODE = #{st_code}
AND UPPER(DE.TEXT1) LIKE UPPER('%' || #{st_name} || '%')
AND DECODE(NVL(PS.CODE, '0'), '0', 'N', 'Y') = #{st_dept_type}
ORDER BY DEPT_TYPE DESC , DE.CODE

/*selectMasterMdAmMasterCodeManageCheck*/

		SELECT
		    CODE
		FROM  ICOMCOD2 /* 회사별 코드관리 */
		WHERE 1=1
		AND COMPANY_CODE = #{st_com_code}
		AND TYPE = #{st_type}
		AND CODE = #{CODE}

/*selectMasterMdAmMasterCodeManageAccountCheck*/

		SELECT
		    DECODE(COUNT(*),0,'XX','OO') AS MODIFY_FLAG
		FROM
		    ICOMBDGT /* 부서별 예산관리 */
		WHERE 1=1
		AND BUYER = #{st_com_code}
		AND ACCOUNT_TYPE = #{CODE}
		AND TO_CHAR(SYSDATE, 'YYYYMMDD') BETWEEN FROM_DATE AND TO_DATE

