/*insertMasterMdAmMasterCodeManage*/

		INSERT INTO ICOMCOD2 /* 회사별 코드관리 */
		(
		    TYPE
		  , CODE
		  , COMPANY_CODE
		  , TEXT1
		  , TEXT2
		  , FLAG
		  , TEXT3
		  , TEXT4
		  , ADD_DATE


		  , TEXT5
		  , TEXT6



		  , TYPE_FLAG



		)
		VALUES
		(
		    #{st_type}
		  , #{CODE}
		  , #{st_com_code}
		  , #{TEXT1}
		  , #{TEXT2}


		  , 'Y'


		  , #{FLAG}


		  , #{TEXT3}
		  , #{TEXT4}
		  , TO_CHAR(SYSDATE , 'YYYYMMDD')


		  , #{TEXT5}
		  , #{TEXT6}



		  , DECODE(#{DEPT_TYPE}, 'N', 'A', 'Y', 'A', #{DEPT_TYPE})



		)

/*updateMasterMdAmMasterCodeManage*/

		UPDATE ICOMCOD2 /* 회사별 코드관리 */
		SET CODE  = #{CODE}
		  , TEXT1 = #{TEXT1}
		  , TEXT2 = #{TEXT2}
		  , TEXT3 = #{TEXT3}
		  , TEXT4 = #{TEXT4}


		  , TEXT5 = #{TEXT5}
		  , TEXT6 = #{TEXT6}


		  , FLAG = #{FLAG}



		  , TYPE_FLAG = DECODE(#{DEPT_TYPE}, 'N', 'A', 'Y', 'A', #{DEPT_TYPE})



		WHERE 1=1
		AND TYPE  = #{st_type}
		AND CODE  = #{ORG_CODE}
		AND COMPANY_CODE = #{st_com_code}

/*deleteMasterMdAmMasterCodeManage*/

		DELETE FROM ICOMCOD2 /* 회사별 코드관리 */
		WHERE 1=1
		AND TYPE  = #{st_type}
		AND CODE  = #{ORG_CODE}
		AND COMPANY_CODE = #{st_com_code}
